    expect_failure(fn() => record_wang_weighing($testDb, $dayOne, '10', $morningPrice, 'test', '1', $otherRound), 'Weighing rejects a placement from another selected round');
    $nextPurchase = record_wang_weighing($testDb, $dayOne, '10', $morningPrice, 'test', '1', $nextRound);
    $testDb->query("UPDATE tbl_price SET pr_price=80 WHERE pr_id=$morningPrice");
    $snapshot = weighing_for_rubber($testDb, $nextPurchase);
    check($snapshot['price_per_kg'] === '46.00' && $snapshot['round_date'] === '2026-10-27' && (int)$snapshot['collection_round_id'] === $nextRound, 'Confirmed weighing freezes price while retaining the configured sale round');
    expect_failure(fn() => approve_weighed_purchase($testDb, $nextPurchase, 'review', 'test', $otherRound), 'Approval rejects cross-round requests');
    approve_weighed_purchase($testDb, $nextPurchase, 'review', 'test', $nextRound);
    expect_failure(fn() => return_weighed_purchase_to_approval($testDb, $nextPurchase, 'test', $otherRound), 'Return-to-approval rejects cross-round requests');
    save_round_rubber_deductions($testDb, $nextPurchase, ['ru_loan'=>'10'], 'finance', $nextRound);
    $frozenPurchase = $testDb->query("SELECT * FROM tbl_rubber WHERE ru_id=$nextPurchase")->fetch_assoc();
    check($frozenPurchase['ru_value'] === '460.00' && $frozenPurchase['ru_netvalue'] === '450.00', 'Deductions use the frozen price, not a later price revision');
    // An older price date inserted later must not replace the latest price date.
    $testDb->query("INSERT INTO tbl_price (pr_year,pr_number,pr_date,pr_price,pr_saveby,pr_savedate) VALUES (2569,'older-insert','2026-10-26',999,'test','2026-10-29')");
    check((int)latest_rubber_price($testDb)['pr_id'] === $morningPrice, 'A late insertion with an older price date does not replace the latest price');
    $testDb->query("INSERT INTO tbl_price (pr_year,pr_number,pr_date,pr_price,pr_saveby,pr_savedate,collection_round_id) VALUES (2569,'same-date-revision','2026-10-27',47,'test','2026-10-27',$nextRound)");
    $lateEveningPrice = (int)$testDb->insert_id;
    $secondPurchase = record_wang_weighing($testDb, $dayTwo, '10', $lateEveningPrice, 'test', '1', $nextRound);
    check($testDb->query("SELECT ru_date FROM tbl_rubber WHERE ru_id=$secondPurchase")->fetch_row()[0] === '2026-10-27', 'The weighing snapshot uses the latest price date');
    check(weighing_for_rubber($testDb, $secondPurchase)['price_per_kg'] === '47.00', 'Newest price ID wins when the price date is the same');
    $badPlacement = $testDb->prepare("INSERT INTO tbl_wangyang (wang_date,wang_name,wang_savedate) VALUES ('2026-10-24','Out of window',NOW())");
    expect_failure(fn() => execute_wang_with_audit($testDb, $badPlacement, 0, 'placement_create', $nextRound), 'Placement outside the configured two-day window is rolled back');
    $badPlacement->close();
    $reportPrices = $testDb->query(collection_price_dates_sql())->fetch_all(MYSQLI_ASSOC);
    $reportPrices = array_column($reportPrices, 'pr_price', 'pr_date');
    check(($reportPrices['2026-10-27'] ?? null) === '47.00' && isset($reportPrices['2026-10-21']), 'Reporting uses the actual price dates without manual round remapping');
    $testDb->query("INSERT INTO tbl_price (pr_year,pr_number,pr_date,pr_price,pr_saveby,pr_savedate) VALUES (2569,'latest-window','2026-10-28',48,'test','2026-10-28')");
    $windowPrice = (int)$testDb->insert_id;
    $windowRound = latest_priced_collection_round($testDb);
    check($windowRound['weigh_date'] === '2026-10-28' && $windowRound['lay_start'] === '2026-10-26' && $windowRound['lay_end'] === '2026-10-27', 'Latest price creates the two-day weighing window automatically');
    $testDb->query("INSERT INTO tbl_wangyang (wang_date,wang_group,wang_number,wang_name,wang_class,wang_sack,wang_lan,wang_savedate) VALUES ('2026-10-25','1','201','Too old','member',1,'1',NOW()),('2026-10-26','1','202','Eligible day one','member',1,'1',NOW()),('2026-10-27','1','203','Eligible day two','member',1,'1',NOW()),('2026-10-28','1','204','Price day excluded','member',1,'1',NOW()),('2026-10-29','1','205','Future excluded','member',1,'1',NOW())");
    $boundaryFirst = (int)$testDb->insert_id;
    check(weighing_window_counts($testDb, $windowRound, '1')['pending_weighing'] === 2, 'Queue includes only both preceding days and excludes previously weighed overlapping records');
    expect_failure(fn() => record_wang_weighing($testDb, $boundaryFirst, '10', $windowPrice, 'test', '1'), 'Server rejects dates older than two days before latest price');
    expect_failure(fn() => record_wang_weighing($testDb, $boundaryFirst+3, '10', $windowPrice, 'test', '1'), 'Server rejects placements on the price date itself');
    expect_failure(fn() => record_wang_weighing($testDb, $dayTwo, '10', $windowPrice, 'test', '1'), 'Old weighed records cannot enter a later overlapping window');
    $unassignedPurchase = record_wang_weighing($testDb, $boundaryFirst+1, '10', $windowPrice, 'test', '1');
    check((int)weighing_for_rubber($testDb, $unassignedPurchase)['collection_round_id'] === (int)$windowRound['round_id'], 'Eligible unassigned placement is attached only when weighed');
    check(weighing_window_counts($testDb, $windowRound, '1')['pending_weighing'] === 1, 'A confirmed weighing immediately leaves the pending window');
    // Render the small slip against the isolated database, without touching application records.
    $applicationDatabase = db()->query('SELECT DATABASE()')->fetch_row()[0];
    db()->select_db($name);
    try {
        $testDb->query("UPDATE tbl_wangyang SET wang_note='(บิน)' WHERE wang_id=$wangId");
        $_SESSION['user_id'] = 1;
        $_GET['ru_id'] = $rubberId;
        ob_start();
        require __DIR__ . '/../print_deduction_check.php';
        $slipHtml = ob_get_clean();
        check(str_contains($slipHtml, 'Test member (บิน)') && !str_contains($slipHtml, '((บิน))'), 'Slip displays placement note without duplicate parentheses');
        check(str_contains($slipHtml, '100.50') && str_contains($slipHtml, '4.00') && str_contains($slipHtml, '80mm 60mm'), 'Small slip renders sacks, confirmed weight and paper dimensions');
        $slipContent = explode('</article>', explode('<article class="slip"', $slipHtml, 2)[1], 2)[0];
        check(str_contains($slipContent, 'กลุ่ม:') && !str_contains($slipContent, 'เลขที่') && !str_contains($slipContent, 'ลาน') && !str_contains($slipContent, 'รอบขายยาง') && !str_contains($slipContent, 'ผู้ตรวจสอบ'), 'Slip contains only name, group, sacks and weight');
    } finally {
        db()->select_db($applicationDatabase);
    }
    $sessionBeforeTestMode = $_SESSION;
    $realToday = (new DateTimeImmutable('today', new DateTimeZone('Asia/Bangkok')))->format('Y-m-d');
    $simulatedSale = (new DateTimeImmutable($realToday))->modify('+2 days')->format('Y-m-d');
    $_SESSION['user_id']=1001; $_SESSION['user_username']='same-day-admin'; $_SESSION['user_fullname']='Same day tester'; $_SESSION['user_level']='admin';
    unset($_SESSION['demo_test_sale_date'], $_SESSION['demo_test_user_id']);
    check(!can_weigh_on_price_date($simulatedSale), 'Normal mode blocks future weighing dates');
    $_SESSION['demo_test_sale_date']=$simulatedSale; $_SESSION['demo_test_user_id']=1001;
    check(placement_entry_date() === $realToday && can_weigh_on_price_date($simulatedSale), 'Test mode simulates day-three weighing while placement is recorded on the same real day');
    check(!can_weigh_on_price_date((new DateTimeImmutable($simulatedSale))->modify('+1 day')->format('Y-m-d')), 'Test mode only unlocks its configured sale date');
    $_SESSION['user_level']='user';
    check(demo_test_settings() === null && !can_weigh_on_price_date($simulatedSale), 'Ordinary staff cannot activate test mode through stale session flags');
    $_SESSION['user_level']='admin'; $_SESSION['user_id']=1002;
    check(demo_test_settings() === null, 'Test mode is bound to the admin account that enabled it');
    $_SESSION['user_id']=1001;
    $testDb->query("INSERT INTO tbl_price (pr_year,pr_number,pr_date,pr_price,pr_saveby,pr_savedate) VALUES (2569,'same-day-test','$simulatedSale',55,'test','$realToday')");
    $simulatedPrice=(int)$testDb->insert_id;
    $testDb->query("INSERT INTO tbl_wangyang (wang_date,wang_group,wang_number,wang_name,wang_class,wang_sack,wang_lan,wang_savedate) VALUES ('$realToday','1','999','Same-day test member','member',2,'1',NOW())");
    $simulatedWang=(int)$testDb->insert_id;
    $simulatedPurchase=record_wang_weighing($testDb,$simulatedWang,'10',$simulatedPrice,'test','1');
    $simulatedRound=(int)weighing_for_rubber($testDb,$simulatedPurchase)['collection_round_id'];
    approve_weighed_purchase($testDb,$simulatedPurchase,'review','test',$simulatedRound);
    save_round_rubber_deductions($testDb,$simulatedPurchase,['ru_loan'=>'50'],'test',$simulatedRound);
    check(rubber_receipt_ready($testDb,$simulatedPurchase), 'Same-day test completes weighing, referral and deductions without waiting');
    $simulatedRow=$testDb->query("SELECT * FROM tbl_rubber WHERE ru_id=$simulatedPurchase")->fetch_assoc();
    $testDb->begin_transaction(); lock_rubber_for_edit($testDb,$simulatedPurchase,false); record_rubber_receipt_issue($testDb,$simulatedRow,'test'); $testDb->commit();
    $simulatedReceipt=rubber_receipt_issued($testDb,$simulatedPurchase);
    check($simulatedRow['ru_date'] === $simulatedSale && $simulatedRow['ru_netvalue'] === '500.00' && substr($simulatedReceipt['issued_at'],0,10) === $realToday, 'Test receipt retains simulated sale date, correct totals and real issuance time');
    $testAudit=$testDb->query("SELECT details,recorded_at FROM tbl_collection_audit WHERE ru_id=$simulatedPurchase AND action='weigh'")->fetch_assoc();
    check((json_decode($testAudit['details'],true)['demo_test']['sale_date'] ?? '') === $simulatedSale && substr($testAudit['recorded_at'],0,10) === $realToday, 'Audit marks simulated operations and keeps real timestamps');
    unset($_SESSION['demo_test_sale_date'], $_SESSION['demo_test_user_id']);
    check(demo_test_settings() === null && !can_weigh_on_price_date($simulatedSale), 'Turning test mode off restores the normal weighing date restriction');
    $_SESSION=$sessionBeforeTestMode;
    $testDb->query("CREATE TABLE IF NOT EXISTS tbl_member (mem_id INT PRIMARY KEY, mem_fullname VARCHAR(255)) ENGINE=InnoDB");
    $testDb->query("CREATE TABLE IF NOT EXISTS tbl_user (user_id INT PRIMARY KEY, user_username VARCHAR(255)) ENGINE=InnoDB");
    $testDb->query("INSERT INTO tbl_member VALUES (1,'Keep member')");
    $testDb->query("INSERT INTO tbl_user VALUES (1,'Keep account')");
    $_SESSION['user_level'] = 'user';
    expect_failure(fn() => clear_demo_data($testDb, true, 'not-admin'), 'Non-admin cannot clear demo data');
    $_SESSION['user_level'] = 'admin';
    $beforeReset = demo_reset_inventory($testDb);
    $testDb->query("CREATE TRIGGER fail_demo_reset BEFORE DELETE ON tbl_rubber FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Simulated reset failure'");
    expect_failure(fn() => clear_demo_data($testDb, false, 'reset-admin'), 'Reset failure rolls back all deletions');
    $afterFailedReset = demo_reset_inventory($testDb);
    check(array_column($beforeReset, 'count') === array_column($afterFailedReset, 'count'), 'Failed reset preserves every table count including receipts and history');
    $testDb->query('DROP TRIGGER fail_demo_reset');
    clear_demo_data($testDb, false, 'reset-admin');
    foreach (demo_reset_inventory($testDb) as $table=>$item) {
        $expected = in_array($table, ['tbl_member','tbl_collection_audit'], true) ? 1 : 0;
        check($item['count'] === $expected, "Demo reset clears $table with members retained by default");
    }
    check((int)$testDb->query('SELECT COUNT(*) FROM tbl_user')->fetch_row()[0] === 1, 'Demo reset retains login accounts');
    check($testDb->query('SELECT action FROM tbl_collection_audit')->fetch_row()[0] === 'demo_reset', 'Reset records the responsible actor and new reset event');
    clear_demo_data($testDb, true, 'reset-admin');
    check((int)$testDb->query('SELECT COUNT(*) FROM tbl_member')->fetch_row()[0] === 0 && (int)$testDb->query('SELECT COUNT(*) FROM tbl_user')->fetch_row()[0] === 1, 'Optional member reset still retains user accounts');
    check(latest_priced_collection_round($testDb) === null, 'No price does not require manual round configuration');
    $noPricePlacement = $testDb->prepare("INSERT INTO tbl_wangyang (wang_date,wang_name,wang_savedate) VALUES ('2026-10-29','Placement before price',NOW())");
    execute_wang_with_audit($testDb, $noPricePlacement, 0, 'placement_create');
    $beforePriceId = (int)$noPricePlacement->insert_id; $noPricePlacement->close();
    check($testDb->query("SELECT collection_round_id FROM tbl_wangyang WHERE wang_id=$beforePriceId")->fetch_row()[0] === null, 'Placement can be saved on any day without a price or configured round');
    echo "All weighing checks passed.\n";
} finally {
    $testDb->query("DROP DATABASE `$name`");
}
